// src/pages/Favorites.jsx
import React, { useEffect, useState, useCallback } from 'react';
import Header from '../components/Header';
import Card from '../components/Card';
import api from '../utils/api';
import { getIds } from '../utils/favStorage';

const Favorites = () => {
  const [listMoviesData, setListMoviesData] = useState([]);
  const [loading, setLoading] = useState(true);

  const load = useCallback(async () => {
    setLoading(true);
    try {
      // IDs depuis localStorage (parser robuste via favStorage)
      const ids = getIds();
      if (!ids.length) {
        setListMoviesData([]);
        return;
      }

      // Charger les détails pour chaque ID
      const movies = await Promise.all(
        ids.map(id =>
          api
            .get(`/movies/${id}`, { params: { language: 'fr-FR' } })
            .then(r => r.data)
            .catch(err => {
              console.error(`Erreur film ${id}`, err);
              return null;
            })
        )
      );

      setListMoviesData(movies.filter(Boolean));
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    // premier chargement
    load();

    // se rafraîchit quand la liste de favoris change (événement custom émis par favStorage)
    const onFavsChanged = () => load();
    window.addEventListener('favorites:changed', onFavsChanged);
    return () => window.removeEventListener('favorites:changed', onFavsChanged);
  }, [load]);

  return (
    <div className="user-list-page">
      <Header />

      <h2>
        Films Préférés <span>💛</span>
      </h2>

      {loading ? (
        <p>Chargement des favoris…</p>
      ) : (
        <div className="result">
          {listMoviesData.length === 0 ? (
            <p>Aucun film favori pour l'instant</p>
          ) : (
            listMoviesData.map((movie) => <Card movie={movie} key={movie.id} />)
          )}
        </div>
      )}
    </div>
  );
};

export default Favorites;



