// src/utils/favStorage.js
const KEY = 'movies';

function parseIds(raw) {
    if (!raw) return [];
    try {
        if (raw.trim().startsWith('[')) {
            const arr = JSON.parse(raw);
            return Array.isArray(arr) ? arr.map(Number).filter(Number.isFinite) : [];
        }
    } catch (_) { }
    return raw
        .split(',')
        .map(s => Number(String(s).trim()))
        .filter(Number.isFinite);
}

export function getIds() {
    return Array.from(new Set(parseIds(localStorage.getItem(KEY) || '')));
}

export function setIds(ids) {
    const clean = Array.from(new Set((ids || []).map(Number).filter(Number.isFinite)));
    localStorage.setItem(KEY, clean.join(','));
    // notifie le même onglet (Favorites écoutera cet événement)
    window.dispatchEvent(new CustomEvent('favorites:changed', { detail: clean }));
    return clean;
}

export function addId(id) {
    const curr = getIds();
    if (!curr.includes(Number(id))) curr.push(Number(id));
    return setIds(curr);
}

export function removeId(id) {
    const next = getIds().filter(x => x !== Number(id));
    return setIds(next);
}

export function toggleId(id) {
    const curr = getIds();
    const i = curr.indexOf(Number(id));
    if (i >= 0) curr.splice(i, 1);
    else curr.push(Number(id));
    return setIds(curr);
}
